SELECT  coalesce(json_agg("root" ORDER BY "root.pg.nickname" ASC NULLS LAST, "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."nickname" AS "nickname"       ) AS "_e"      ) ) AS "root", "_root.base"."nickname" AS "root.pg.nickname", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "nickname" ASC NULLS LAST, "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.nickname" ASC NULLS LAST, "root.pg.id" ASC NULLS LAST  ) AS "_root"
